local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_FAREWELL, 'Good bye! And remember: No running up and down in the academy!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'Good bye! And remember: No running up and down in the academy!')
keywordHandler:addKeyword({'willie'}, StdModule.say, {npcHandler = npcHandler, text = 'Willie is a fine farmer, although he has short temper.'})
keywordHandler:addKeyword({'castle'}, StdModule.say, {npcHandler = npcHandler, text = 'The castle of Thais is the greatest achievement in Tibian history.'})
keywordHandler:addKeyword({'weapon'}, StdModule.say, {npcHandler = npcHandler, text = 'You need fine weapons to fight the tougher beasts. Unfortunately only the most basic weapons and armor are available here. You will have to fight some monsters to get a better weapon.'})
keywordHandler:addKeyword({'dallheim'}, StdModule.say, {npcHandler = npcHandler, text = 'Oh good Dallheim! What a fighter he is! Without him we would be doomed.'})
keywordHandler:addKeyword({'monster'}, StdModule.say, {npcHandler = npcHandler, text = 'You can learn about Tibia\'s monsters in our library.'})
keywordHandler:addKeyword({'gamemaster'}, StdModule.say, {npcHandler = npcHandler, text = 'If you have serious problems with the game or with other people who are harassing you, contact a counsellor or a gamemaster using CTRL+R.'})
keywordHandler:addKeyword({'sell'}, StdModule.say, {npcHandler = npcHandler, text = 'I sell the Key to Adventure for 5 gold! If you are interested, tell me that you want to buy the key.'})
keywordHandler:addKeyword({'help'}, StdModule.say, {npcHandler = npcHandler, text = 'I can assist you with my advice.'})
keywordHandler:addKeyword({'train'}, StdModule.say, {npcHandler = npcHandler, text = 'You can try some basic things down there, but don\'t challenge the monsters in our arena if you are inexperienced.'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'Hail to King Tibianus! Long live our king! Not that he cares for an old veteran who is stuck on this godforsaken island...'})
keywordHandler:addKeyword({'amber'}, StdModule.say, {npcHandler = npcHandler, text = 'A traveller from the main land. I wonder what brought her here, since no one comes here of his own free will.'})
keywordHandler:addKeyword({'sir'}, StdModule.say, {npcHandler = npcHandler, text = 'At least you know how to address a man of my importance.'})
keywordHandler:addKeyword({'tibia'}, StdModule.say, {npcHandler = npcHandler, text = 'Oh, how I miss the crowded streets of Thais. I know one day I will get promoted and get a job at the castle... I must get out of here! The faster the better! It is people like you who are driving me mad.'})
keywordHandler:addKeyword({'sewer'}, StdModule.say, {npcHandler = npcHandler, text = 'Our sewers are overrun with rats. If you own some equipment you could go down a sewer grate and fight the vermin.'})
keywordHandler:addKeyword({'advice'}, StdModule.say, {npcHandler = npcHandler, text = 'Read the blackboard for some hints and visit the training center in the cellar.'})
keywordHandler:addKeyword({'time'}, StdModule.say, {npcHandler = npcHandler, text = 'It is the current time, so you are late. Hurry!'})
keywordHandler:addKeyword({'library'}, StdModule.say, {npcHandler = npcHandler, text = 'Go and read our books. Ignorance may mean death, so be careful.'})
keywordHandler:addKeyword({'quentin'}, StdModule.say, {npcHandler = npcHandler, text = 'He is responsible for the temple in Thais.'})
keywordHandler:addKeyword({'oracle'}, StdModule.say, {npcHandler = npcHandler, text = 'You will find the oracle upstairs. Talk to the oracle as soon as you have made level 8. Choose a vocation and a new home town, and you will be sent off to the continent.'})
keywordHandler:addKeyword({'god'}, StdModule.say, {npcHandler = npcHandler, text = 'You can learn much about Tibia\'s gods in our library.'})
keywordHandler:addKeyword({'magic'}, StdModule.say, {npcHandler = npcHandler, text = 'The only magic-user on this isle is old Hyacinth.'})
keywordHandler:addKeyword({'obi'}, StdModule.say, {npcHandler = npcHandler, text = 'A cousin of Thais\' smith Sam. He has a shop here where you can buy most stuff an adventurer needs.'})
keywordHandler:addKeyword({'academy'}, StdModule.say, {npcHandler = npcHandler, text = 'Our academy has a library, a training center in the cellars and the oracle upstairs.'})
keywordHandler:addKeyword({'hyacinth'}, StdModule.say, {npcHandler = npcHandler, text = 'A mysterious druid who lives somewhere in the wilderness. He sells precious life fluids.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I am the master of this fine academy.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'My name is Seymour, but to you I am \'Sir\' Seymour.'})
keywordHandler:addKeyword({'cipfried'}, StdModule.say, {npcHandler = npcHandler, text = 'A humble monk with healing powers, and a pupil of the great Quentin himself.'})
keywordHandler:addKeyword({'rookgaard'}, StdModule.say, {npcHandler = npcHandler, text = 'Here on Rookgaard we have some people, a temple, some shops, a farm and an academy.'})
keywordHandler:addKeyword({'bug'}, StdModule.say, {npcHandler = npcHandler, text = 'Nasty little creatures, but once you have a suitable weapon and perhaps a shield they will be no match for you.'})
keywordHandler:addKeyword({'people'}, StdModule.say, {npcHandler = npcHandler, text = 'Well, there\'s me, Cipfried, Willie, Obi, Amber, Dallheim, Al Dee, Norma, and Hyacinth.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)
shopModule:addBuyableItem({'key'}, 2969, 5, 'key')
shopModule:addBuyableItem({'rat'}, 3994, 2, 'rat')

local focusModule = FocusModule:new()
focusModule:addGreetMessage('hi')
focusModule:addGreetMessage('hello')
npcHandler:addModule(focusModule)

